'use strict';
const BASE_URL=new URL('./',document.querySelector('script[src$="admin.js"]').src);
const original={tutorials:JSON.parse(JSON.stringify(tutorials)),videos:JSON.parse(JSON.stringify(videos)),faq:JSON.parse(JSON.stringify(faq))};
let data=structuredClone(original),assets=new Map(),tab='tutorials',selected=data.tutorials[0].id,stepIndex=0,db=null,saveTimer,previewURL=null;
const $=s=>document.querySelector(s),escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const say=(text,error=false)=>{$('#message').textContent=text;$('#message').classList.toggle('error',error)};
const roleLabel=r=>r==='manager'?'Lãnh đạo':r==='employee'?'Cán bộ':'Công việc cá nhân (dùng chung)';
const current=()=>data.tutorials.find(t=>t.id===selected);
function field(label,key,value,wide=false,type='input',options=[]){return `<label class="field ${wide?'wide':''}">${label}${type==='textarea'?`<textarea data-field="${key}">${escapeHTML(value)}</textarea>`:type==='select'?`<select data-field="${key}">${options.map(o=>`<option value="${escapeHTML(o[0])}" ${String(value??'')===String(o[0])?'selected':''}>${escapeHTML(o[1])}</option>`).join('')}</select>`:`<input data-field="${key}" value="${escapeHTML(value)}" ${type==='number'?'type="number" min="1" max="29"':''}>`}</label>`}
function render(){document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('selected',b.dataset.tab===tab));if(tab==='help'){help();return}if(tab==='videos'){videoEditor();return}const t=current()||data.tutorials[0];selected=t.id;stepIndex=Math.min(stepIndex,t.steps.length-1);const s=t.steps[stepIndex];$('#editor').innerHTML=`<div class="editor-layout"><aside class="editor-list"><input id="filter" type="search" aria-label="Tìm hướng dẫn" placeholder="Tìm hướng dẫn…"><div class="tutorial-list">${data.tutorials.map(x=>`<button class="tutorial-select ${x.id===selected?'active':''}" data-tutorial="${x.id}">${escapeHTML(x.title)}<small>${roleLabel(x.role)} · ${x.steps.length} bước</small></button>`).join('')}</div><button class="button secondary" data-action="add-tutorial">＋ Thêm hướng dẫn</button></aside><section class="editor-panel"><h2>Thông tin hướng dẫn</h2><p class="source-line">Mã: <b>${escapeHTML(t.id)}</b> · Chỉ sửa quy trình khi đã đối chiếu nguồn.</p><div class="fields">${field('Tên hướng dẫn','tutorial.title',t.title,true)}${field('Mô tả ngắn','tutorial.description',t.description,true,'textarea')}${field('Vai trò','tutorial.role',t.role,false,'select',[['both','Công việc cá nhân (dùng chung)'],['employee','Chỉ Cán bộ'],['manager','Chỉ Lãnh đạo']])}${field('Biểu tượng','tutorial.icon',t.icon,false,'select',['edit','inbox','chart','send','clock','star','user','lock','bell','check','plus','grid','file','video'].map(x=>[x,x]))}${field('Từ khóa tìm kiếm (ngăn bằng dấu phẩy)','tutorial.keywords',t.keywords.join(', '),true)}${field('Thông báo khi xem xong','tutorial.result',t.result,true,'textarea')}${field('Hướng dẫn tiếp theo','tutorial.next',t.next||'',false,'select',[['','Không có'],...data.tutorials.filter(x=>x.id!==t.id).map(x=>[x.id,x.title])])}${field('Tài liệu nguồn','tutorial.source',t.source||'',false,'select',[['','Ảnh / quy trình được xác nhận'],['employee','PDF Chuyên viên'],['manager','PDF Lãnh đạo']])}${field('Trang bắt đầu trong PDF','tutorial.page',t.page||1,false,'number')}</div><div class="steps-editor"><h2>Các bước thực hiện</h2><div class="step-tabs">${t.steps.map((x,i)=>`<button data-step="${i}" class="${i===stepIndex?'active':''}">Bước ${i+1}</button>`).join('')}</div><div class="fields">${field('Tên bước','step.title',s.title,true)}${field('Chỉ dẫn thao tác','step.instruction',s.instruction,true,'textarea')}${field('Tên ảnh trong thư mục assets','step.image',s.image,true)}<label class="field wide">Thay ảnh (PNG, JPG, WebP; tối đa 10 MB)<input id="upload-image" type="file" accept="image/png,image/jpeg,image/webp"><small>Ảnh mới sẽ được đưa vào gói ZIP cập nhật.</small></label>${field('Lưu ý quan trọng','step.warning',s.warning||'',true,'textarea')}${field('Ghi nhớ','step.tip',s.tip||'',true,'textarea')}${field('Khoanh nút Sửa (chỉ đúng với ảnh KPI hiện tại)','step.highlight',s.highlight||'',true,'select',[['','Không khoanh'],['edit-kpi','Khoanh nút Sửa trên ảnh employee-17-3.png']])}</div><div class="step-tools"><button data-action="move-up" ${stepIndex===0?'disabled':''}>↑ Đưa lên</button><button data-action="move-down" ${stepIndex===t.steps.length-1?'disabled':''}>↓ Đưa xuống</button><button data-action="add-step">＋ Thêm bước</button><button data-action="delete-step" class="danger" ${t.steps.length===1?'disabled':''}>Xóa bước</button></div><div class="preview"><h3>Xem trước bước ${stepIndex+1}</h3><h3 id="preview-title"></h3><p id="preview-instruction"></p><span class="annotated-image"><img id="preview-image" alt="Ảnh xem trước"><span id="preview-highlight" class="edit-kpi-circle" hidden></span></span><p id="image-error" class="danger-text" hidden>Không tải được ảnh. Kiểm tra tên file hoặc tải ảnh mới lên.</p><div id="preview-warning" class="preview-note warning" hidden></div><div id="preview-tip" class="preview-note" hidden></div></div></div><div class="editor-bottom"><a class="text-link" href="${new URL('?viec='+t.id,BASE_URL)}" target="_blank" rel="noopener">Xem phiên bản đã xuất bản ↗</a><button class="button secondary danger-text" data-action="delete-tutorial">Xóa hướng dẫn</button></div></section></div>`;updatePreview()}
function updatePreview(){if(tab!=='tutorials')return;const s=current().steps[stepIndex];$('#preview-title').textContent=s.title;$('#preview-instruction').textContent=s.instruction;for(const key of ['tip','warning']){const el=$('#preview-'+key);el.textContent=s[key]||'';el.hidden=!s[key]}if(previewURL){URL.revokeObjectURL(previewURL);previewURL=null}const f=assets.get(s.image);if(f)previewURL=URL.createObjectURL(f);const img=$('#preview-image');img.onerror=()=>{$('#image-error').hidden=false};img.onload=()=>{$('#image-error').hidden=true};img.src=previewURL||new URL('assets/'+s.image,BASE_URL);$('#preview-highlight').hidden=s.highlight!=='edit-kpi'}
function videoEditor(){$('#editor').innerHTML=`<section class="editor-panel"><h2>Video hướng dẫn</h2><p class="intro">Dán link YouTube hoặc mã video. Khi xuất dữ liệu, hệ thống giữ mã video 11 ký tự.</p>${data.videos.map((v,i)=>`<div class="video-fields"><div class="fields">${field('Tên video',`video.${i}.title`,v.title,true)}${field('Vai trò',`video.${i}.role`,v.role,false,'select',[['employee','Cán bộ'],['manager','Lãnh đạo']])}${field('Link YouTube hoặc mã video',`video.${i}.id`,v.id)}<a class="text-link" id="video-link-${i}" href="https://youtu.be/${escapeHTML(v.id)}" target="_blank" rel="noopener">Xem video ↗</a></div></div>`).join('')}</section>`}
function help(){$('#editor').innerHTML=`<section class="editor-panel help-panel"><h2>Cập nhật website trong 4 bước</h2><ol><li><b>Sửa nội dung:</b> chọn hướng dẫn, sửa từng bước, thay ảnh và kiểm tra phần xem trước.</li><li><b>Tải gói cập nhật ZIP:</b> gói có <code>dist/data.js</code>, bản sao lưu và các ảnh mới trong <code>dist/assets/</code>.</li><li><b>Cập nhật kho Git:</b> giải nén, chép đè vào thư mục source. Đưa các file thay đổi lên Git và commit. Lưu ý giữ cả thư mục <code>.github</code> từ bộ source đầy đủ.</li><li><b>Chờ GitHub Pages triển khai:</b> khi workflow thành công, mở link website và kiểm tra. Gửi link này cho đơn vị.</li></ol><h3>Lần đầu triển khai</h3><p>Dùng toàn bộ bộ source ZIP đã được gửi. Trên GitHub, chọn <b>Settings → Pages → Source: GitHub Actions</b>. Workflow kèm theo tự chuẩn bị đường dẫn và xuất bản khi đẩy lên nhánh <code>main</code>.</p><h3>Bản nháp và bản sao lưu</h3><p>Bản nháp nằm trong trình duyệt hiện tại. Khi đổi máy hoặc xóa dữ liệu trình duyệt, dùng <b>Sao lưu JSON</b> và <b>Nhập bản sao lưu</b> để chuyển nội dung cùng các ảnh mới. File nhập chỉ nhận JSON, không chạy JavaScript.</p><h3>Quyền quản trị</h3><p>Trang biên tập không yêu cầu tài khoản, vì không thể sửa website trực tiếp. Quyền xuất bản thực tế thuộc người có quyền ghi vào kho Git. Bản nháp của người này không ảnh hưởng đến bản nháp của người khác.</p></section>`}
function changed(){$('#draft-status').textContent='Có thay đổi chưa lưu';clearTimeout(saveTimer);saveTimer=setTimeout(()=>saveDraft(false),1000)}
async function openDB(){return new Promise((resolve,reject)=>{const req=indexedDB.open('note-kpi-editor-v2',1);req.onupgradeneeded=()=>req.result.createObjectStore('draft');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
async function saveDraft(explicit=true){clearTimeout(saveTimer);if(!db){if(explicit)say('Không lưu được trên trình duyệt. Hãy tải bản sao lưu JSON.',true);return}try{await new Promise((resolve,reject)=>{const tx=db.transaction('draft','readwrite');tx.objectStore('draft').put({data:structuredClone(data),assets:Array.from(assets.entries()),savedAt:Date.now()},'current');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});$('#draft-status').textContent='Đã lưu bản nháp lúc '+new Date().toLocaleTimeString('vi-VN');if(explicit)say('Đã lưu trên trình duyệt này. Website chưa thay đổi.')}catch(e){$('#draft-status').textContent='Chưa lưu được';say('Không lưu được bản nháp: '+e.message+'. Hãy tải JSON để giữ nội dung.',true)}}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000)}
const stamp=()=>new Date().toISOString().slice(0,10);
async function backup(){const list=[];for(const [name,blob]of assets){const b64=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=()=>reject(r.error);r.readAsDataURL(blob)});list.push({name,type:blob.type,data:b64})}return{schemaVersion:1,...structuredClone(data),addedImages:list}}
function validateImages(){for(const t of data.tutorials)for(const s of t.steps)if(s.highlight==='edit-kpi'&&s.image!=='employee-17-3.png')throw Error('Vòng khoanh nút Sửa chỉ đúng với ảnh employee-17-3.png. Bỏ khoanh khi thay ảnh.');}
async function exportZip(){try{AdminCore.validateContent(data);validateImages();const b=await backup(),files=[{name:'dist/data.js',content:AdminCore.dataScript(data)},{name:'note-kpi-backup.json',content:JSON.stringify(b,null,2)},{name:'HUONG-DAN-CAP-NHAT.txt',content:'Chép dist/data.js và các file trong dist/assets/ vào source, thay thế file cũ. Commit và đẩy lên Git. Không chép bản sao lưu JSON lên thư mục website. Chờ workflow GitHub Pages thành công rồi kiểm tra website.'}];for(const [name,blob]of assets)files.push({name:'dist/assets/'+name,content:blob});say('Đang đóng gói dữ liệu…');download(await AdminCore.makeZip(files),'NOTE-KPI-cap-nhat-'+stamp()+'.zip');say('Đã tải gói cập nhật. Giải nén và chép vào source, rồi đẩy lên Git để xuất bản.')}catch(e){say(e.message,true)}}
async function importJSON(file){try{if(!file||file.size>100*1024*1024)throw Error('File sao lưu phải nhỏ hơn 100 MB.');const parsed=JSON.parse(await file.text());AdminCore.validateContent(parsed);const pending=new Map();for(const a of parsed.addedImages||[]){if(!/^[-a-zA-Z0-9_]+\.(png|jpg|jpeg|webp)$/i.test(a.name)||!['image/png','image/jpeg','image/webp'].includes(a.type)||typeof a.data!=='string')throw Error('Ảnh trong bản sao lưu không hợp lệ.');const raw=atob(a.data);if(raw.length>10*1024*1024)throw Error('Ảnh vượt 10 MB.');const blob=new Blob([Uint8Array.from(raw,c=>c.charCodeAt(0))],{type:a.type});const bitmap=await createImageBitmap(blob);bitmap.close();pending.set(a.name,blob)}if(!confirm('Thay bản nháp hiện tại bằng nội dung file nhập?'))return;data={tutorials:parsed.tutorials,videos:parsed.videos,faq:parsed.faq};assets=pending;selected=data.tutorials[0].id;stepIndex=0;render();await saveDraft(false);say('Đã nhập bản sao lưu. Website chưa thay đổi.')}catch(e){say('Không nhập được: '+e.message,true)}}
document.addEventListener('input',e=>{const f=e.target.dataset.field;if(f){const [group,key,last]=f.split('.');if(group==='video'){let value=e.target.value;if(last==='id'){try{if(value.includes('://')){const u=new URL(value);value=u.hostname.includes('youtu.be')?u.pathname.slice(1):u.searchParams.get('v')||u.pathname.split('/').pop()}}catch{}const a=$('#video-link-'+key);a.href='https://youtu.be/'+encodeURIComponent(value)}data.videos[Number(key)][last]=value}else{const obj=group==='step'?current().steps[stepIndex]:current();obj[key]=key==='keywords'?e.target.value.split(',').map(s=>s.trim()).filter(Boolean):key==='page'?Number(e.target.value):e.target.value;updatePreview()}changed()}if(e.target.id==='filter'){const q=e.target.value.toLocaleLowerCase('vi-VN');document.querySelectorAll('[data-tutorial]').forEach(b=>b.hidden=!b.textContent.toLocaleLowerCase('vi-VN').includes(q))}});
document.addEventListener('change',async e=>{if(e.target.id==='upload-image'){try{const file=e.target.files[0];if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>10*1024*1024)throw Error('Chỉ nhận PNG/JPG/WebP tối đa 10 MB.');const bmp=await createImageBitmap(file);bmp.close();const extension=file.type==='image/png'?'png':file.type==='image/webp'?'webp':'jpg';const name='upload-'+Date.now()+'-'+Math.random().toString(36).slice(2,7)+'.'+extension;assets.set(name,file);current().steps[stepIndex].image=name;delete current().steps[stepIndex].highlight;render();changed();say('Đã thay ảnh. Ảnh sẽ đi kèm gói cập nhật.')}catch(err){say(err.message,true)}}if(e.target.id==='import-file'){await importJSON(e.target.files[0]);e.target.value=''}});
document.addEventListener('click',async e=>{const el=e.target.closest('button');if(!el)return;try{if(el.dataset.tab){tab=el.dataset.tab;render();return}if(el.dataset.tutorial){selected=el.dataset.tutorial;stepIndex=0;render();return}if(el.dataset.step!==undefined){stepIndex=Number(el.dataset.step);render();return}if(el.id==='export-zip'){await exportZip();return}if(el.id==='export-json'){download(new Blob([JSON.stringify(await backup(),null,2)],{type:'application/json'}),'NOTE-KPI-sao-luu-'+stamp()+'.json');say('Đã tải bản sao lưu nội dung và ảnh mới.');return}if(el.id==='save-draft'){await saveDraft();return}if(el.id==='import-button'){$('#import-file').click();return}if(el.id==='reset'){if(confirm('Bỏ bản nháp và lấy lại dữ liệu đang có trong website?')){data=structuredClone(original);assets.clear();selected=data.tutorials[0].id;stepIndex=0;render();await saveDraft(false);say('Đã lấy lại dữ liệu website.')}return}const action=el.dataset.action;if(!action)return;const t=current();if(action==='add-tutorial'){const id=prompt('Mã hướng dẫn mới (không dấu, ví dụ: huong-dan-moi):');if(!id)return;if(!/^[a-z][a-z0-9-]*$/.test(id)||data.tutorials.some(t=>t.id===id))throw Error('Mã phải duy nhất và chỉ có chữ không dấu, số, gạch nối.');data.tutorials.push({id,title:'Hướng dẫn mới',description:'',role:'both',icon:'file',keywords:[],source:null,page:null,result:'',steps:[{title:'Bước đầu tiên',instruction:'Nhập chỉ dẫn đã được xác nhận.',image:'employee-17-1.png'}]});selected=id;stepIndex=0}else if(action==='delete-tutorial'){if(data.tutorials.length===1)throw Error('Cần giữ ít nhất một hướng dẫn.');if(!confirm('Xóa hướng dẫn '+t.title+' khỏi bản nháp?'))return;data.tutorials=data.tutorials.filter(x=>x.id!==t.id);for(const x of data.tutorials)if(x.next===t.id)delete x.next;selected=data.tutorials[0].id;stepIndex=0}else if(action==='add-step'){t.steps.splice(stepIndex+1,0,{title:'Bước mới',instruction:'Nhập thao tác đã được xác nhận.',image:t.steps[stepIndex].image});stepIndex++}else if(action==='delete-step'){if(t.steps.length<2)return;if(!confirm('Xóa bước này khỏi bản nháp?'))return;t.steps.splice(stepIndex,1);stepIndex=Math.max(0,stepIndex-1)}else if(action==='move-up'||action==='move-down'){const target=stepIndex+(action==='move-up'?-1:1);if(target<0||target>=t.steps.length)return;[t.steps[target],t.steps[stepIndex]]=[t.steps[stepIndex],t.steps[target]];stepIndex=target}render();changed()}catch(err){say(err.message,true)}});
(async()=>{try{db=await openDB();const saved=await new Promise((resolve,reject)=>{const req=db.transaction('draft').objectStore('draft').get('current');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});if(saved){data=saved.data;assets=new Map(saved.assets);selected=data.tutorials[0].id;$('#draft-status').textContent='Đã khôi phục bản nháp'}else $('#draft-status').textContent='Dữ liệu website hiện tại'}catch(e){$('#draft-status').textContent='Chưa lưu bản nháp';say('Trình duyệt không lưu được bản nháp. Dùng Sao lưu JSON để giữ thay đổi.',true)}render()})();
